namespace Wavebreak.Meta;

/// <summary>Arabic for the weapon and evolution descriptions rewritten when
/// the look-alike weapons were made distinct (docs/weapon-audit.md).</summary>
public static partial class ArabicText
{
    internal static readonly (string En, string Ar)[] DistinctWeapons =
    {
        ("A shard of rail glass, thrown flat and fast. Punches through one body, then breaks into two splinters that fly on.", "شظية زجاج تنطلق مسطّحة وسريعة. تخترق جسدًا واحدًا ثم تنكسر إلى شظيتين صغيرتين تكملان طريقهما."),
        ("Three crackling sparks at once, jittering as they fly. Unfair up close; they fizzle toward the end of their reach.", "ثلاث شرارات طقطاقة معًا، ترتجف وهي تطير. ظالمة من قريب، وتخفت قرب آخر مداها."),
        ("Twin cold edges driven in short, fast lunges, left and right. Narrow, relentless, and very hungry.", "نصلان باردان يندفعان طعنات قصيرة سريعة، يمينًا ويسارًا. ضيّقان، لا يتوقفان، وجائعان جدًا."),
        ("A ring of slow fire that will not go out. It singes what wanders in and burns hotter the longer they stay.", "حلقة نار بطيئة لا تنطفئ. تلسع من يدخلها، وتشتد حرارتها كلما طال بقاؤه."),
        ("A slow, wide pulse that discharges in arcs. It shoves as much as it burns, which is usually what you needed.", "نبضة بطيئة واسعة تتفرّغ في أقواس برق. تدفع بقدر ما تحرق، وهذا غالبًا ما كنت تحتاجه."),
        ("Lobbed high onto a marked spot, slow and enormously final. It flies over everything in between and lands only where it was aimed.", "تُقذف عاليًا نحو بقعة معلَّمة، بطيئة وحاسمة جدًا. تطير فوق كل ما بينهما ولا تسقط إلا حيث صُوّبت."),
        ("Fat spotted pods that burst on contact and split into two seedlings, which hop aside and pop. Not impressive alone. Rarely alone.", "قرون منقّطة ممتلئة تنفجر عند الاصطدام وتنقسم إلى بذرتين تقفزان جانبًا وتنفجران. ليست مبهرة وحدها، ونادرًا ما تكون وحدها."),
        ("Two pale lights that drift and bob a moment before they choose a target, then curve in, patient about reaching it.", "ضوءان شاحبان ينجرفان ويتمايلان لحظة قبل أن يختارا هدفًا، ثم ينعطفان نحوه بصبر."),
        ("It selects one target. After the first strike it stops steering and holds its line, and everything standing behind that target pays.", "يختار هدفًا واحدًا. بعد الضربة الأولى يكف عن التوجيه ويثبت على خطه، فيدفع الثمن كل من يقف خلف ذلك الهدف."),
        ("A barbed spike of crusted salt, thrown hard. It drags what it skewers along the line and bites harder for every body already on it.", "شوكة ملح شائكة تُرمى بقوة. تجرّ ما تخترقه على طول خطها، وتعضّ أشد مع كل جسد عالق بها."),
        ("A stream of drawn-glass needles, one after another, each finding its own aim. Most of them only sting. Some find the seam, and glint when they do.", "سيل من إبر الزجاج المسحوب، واحدة تلو الأخرى، كلٌّ تصوّب بنفسها. معظمها يلسع فقط، وبعضها يجد الشق فيلمع."),
        ("A close ring of cutting cold. It does not push anything away. It draws them gently in; it would rather they stayed.", "حلقة قريبة من برد قاطع. لا تدفع شيئًا بعيدًا، بل تسحبهم إليها برفق؛ تفضّل أن يبقوا."),
        ("Still glowing from the anvil. Brought down overhead, it cracks the ground ahead of you and stuns whatever stands in the middle.", "ما زالت تتوهّج من السندان. تهوي من فوق رأسك فتشقّ الأرض أمامك وتصعق من يقف في وسطها."),
        ("Three fist-sized stones of old ice, thrown low across where they stand. Each skips once and shatters where it lands.", "ثلاث حجارة من جليد قديم بحجم القبضة، تُرمى منخفضة عبر أماكن وقوفهم. تقفز كل واحدة مرة ثم تتحطم حيث تسقط."),
        ("A papery nest that will not stay shut. Each wasp that leaves it picks a different target, and it is never you.", "عش ورقي لا يبقى مغلقًا. كل دبور يخرج منه يختار هدفًا مختلفًا، ولن تكون أنت أبدًا."),
        ("A single white-hot bolt from very far away, at the toughest thing in reach. It leaves a line of smoke and arrives before the sound does.", "سهم واحد أبيض من شدة الحرارة من بعيد جدًا، نحو أقوى ما في المدى. يترك خط دخان ويصل قبل الصوت."),
        ("A brass spindle wound with live weather. Each thread corkscrews out, and after every throat it finds it snaps on to one it has not touched yet.", "مغزل نحاسي ملفوف بطقس حي. كل خيط ينطلق لولبيًا، وبعد كل حلق يصيبه يقفز إلى حلق لم يلمسه بعد."),
        ("A lamp meant to warn ships off the rocks, turned on the things that came out of them. The beam sweeps across them as the lamp turns.", "مصباح وُضع لتحذير السفن من الصخور، صار مسلّطًا على ما خرج منها. يكنسهم الشعاع وهو يدور مع المصباح."),
        ("Flick throws twin storm blades at nearby enemies. They tack side to side on the way out and cut again on the way back, even while standing still. Movement adds up to 25% damage.", "يرمي فليك نصلي عاصفة نحو الأعداء القريبين. يتعرّجان يمينًا ويسارًا في الذهاب ويقطعان مجددًا في العودة، حتى وهو واقف. الحركة تضيف حتى 25% ضررًا."),
        ("The needles ride the wind in a wide loop, through the nearest of them and round again, and the wind brings them home.", "تركب الإبر الريح في حلقة واسعة، تمر بأقربهم وتدور ثانية، ثم تعيدها الريح إليك."),
        ("The spindles stop leaving. They wheel around you, breathing in and out, and everything that comes close is cut to ribbons.", "تكف المغازل عن الرحيل. تدور حولك وتتّسع وتضيق كأنها تتنفّس، وكل من يقترب يُقطّع إربًا."),
        ("You stop aiming. A ship's broadside of cannonballs comes in at a slant and walks a row of blasts through the nearest of them.", "تتوقف عن التصويب. تنهال قذائف مدافع سفينة كاملة مائلةً، وتمشي صفًّا من الانفجارات عبر أقربهم."),
        ("The cold stops waiting for enemies to come close. Rings of frost spikes march outward from you, step by step, in a slow, killing tide.", "يكف البرد عن انتظار اقتراب الأعداء. حلقات من أشواك الصقيع تزحف منك خطوة خطوة، في مدّ بطيء قاتل."),
        ("The hail stops falling and starts circling, wandering after the pack and dragging it into one point before it all lets go.", "يكف البَرَد عن السقوط ويبدأ بالدوران، يلاحق القطيع ويجرّه إلى نقطة واحدة قبل أن ينفجر كله."),
        ("It no longer stops at the far end of the line. It turns, finds the next body, hooks it and reels it toward you.", "لم يعد يتوقف عند نهاية الخط. يستدير ويجد الجسد التالي، يعلقه ويسحبه نحوك."),
        ("The swarm builds a hive where you stand, and keeps sending out wasps that pick their own targets long after you walk on.", "يبني السرب خلية حيث تقف، وتظل ترسل دبابير تختار أهدافها بنفسها حتى بعد أن تمضي."),
        ("The halo burns white, and burning pieces of it fall at a slant on whatever dares to stand nearby.", "تتوهّج الهالة بيضاء، وتسقط قطع مشتعلة منها مائلةً على كل من يجرؤ على الوقوف قريبًا."),
        ("The ground gives up. Each blow raises a line of molten spikes out of the earth, away from you toward the enemy.", "تستسلم الأرض. كل ضربة ترفع صفًّا من أشواك منصهرة من باطن الأرض، منك نحو العدو."),
        ("Every swing keeps going: a wall of water rolls forward from the blade and cuts whatever it reaches.", "كل ضربة تستمر: جدار من الماء يتدحرج إلى الأمام من النصل ويقطع كل ما يبلغه."),
        ("The pods take root where they burst, and a patch of poison spores spreads there for a long while.", "تتجذّر القرون حيث تنفجر، وتنتشر هناك رقعة من أبواغ سامة لوقت طويل."),
        ("The wisps sing as they go, and each verse sends slow motes of cold light spiralling out around you.", "تغنّي الأطياف وهي تمضي، وكل مقطع يرسل ذرّات بطيئة من ضوء بارد تدور لولبيًا حولك."),
        ("The field fills until it cannot hold, then forks lightning into everything around you.", "يمتلئ الحقل حتى لا يعود يحتمل، ثم يشقّ البرق إلى كل ما حولك."),
        ("A full flock of rings leaves your hands at once, and each kill throws a fan of whalebone splinters on along the blow.", "سرب كامل من الحلقات يغادر يديك دفعة واحدة، وكل قتلة ترمي مروحة من شظايا عظم الحوت في اتجاه الضربة."),
        ("More fins, and they do not forgive: whatever they finish breaks into glass that turns on the nearest body.", "زعانف أكثر، ولا تغفر: كل ما تجهز عليه يتكسر زجاجًا ينقضّ على أقرب جسد."),
        ("The mines breed and bite. Anything they kill throws bits of shell that burst where they land.", "تتكاثر الألغام وتعضّ. كل ما تقتله يرمي قطع صدف تنفجر حيث تسقط."),
        ("A hit is no longer the end of the shot. Whatever it touches bursts into a ring of flame that takes its neighbours with it.", "لم تعد الإصابة نهاية الطلقة. كل ما تلمسه ينفجر حلقةً من اللهب تأخذ جيرانه معه."),
        ("Every pellet carries a shaped charge: the blast goes on through what it hits, in a cone behind it.", "كل حبة تحمل شحنة موجّهة: يكمل الانفجار طريقه عبر ما يصيبه، في مخروط خلفه."),
        ("The lance passes sentence on one body, and the sentence comes down from above on everyone standing beside it.", "يصدر الرمح حكمه على جسد واحد، فينزل الحكم من الأعلى على كل من يقف بجانبه."),
        ("Each cut drags a second cut behind it, a heartbeat later, out of the same cold water, and that one pulls them back toward you.", "كل جرح يجرّ خلفه جرحًا ثانيًا بعد نبضة، من الماء البارد نفسه، والثاني يسحبهم نحوك."),
        ("The pair strikes, and a moment later a line of air further out strikes again.", "يضرب الزوج، وبعد لحظة يضرب خطٌّ من الهواء أبعد مرة أخرى."),
    };
}
